const COMBINED_SOFT_CAP = 180_000

function downloadPacksStaggered(
  files: Array<{ name: string; body: string; mime: string }>,
): void {
  files.forEach((f, i) => {
    window.setTimeout(() => {
      downloadTextFile(f.name, f.body, f.mime)
    }, i * 450)
  })
}

export function exportA1ForDeepSeek(
  bookIndex: BookIndex,
  options: A1DsExportOptions = {},
): { packCount: number; rowCount: number; mode: 'single' | 'packs' } {
  const packs = buildA1DsPacks(bookIndex, options)
  const rowCount = packs.reduce((n, p) => n + p.rows.length, 0)
  if (packs.length === 0) {
    return { packCount: 0, rowCount: 0, mode: 'single' }
  }

  const slug = safeDocSlug(bookIndex.docId)
  if (packs.length === 1) {
    downloadTextFile(
      `${packs[0].filenameBase}.md`,
      packs[0].markdown,
      'text/markdown;charset=utf-8',
    )
    return { packCount: 1, rowCount, mode: 'single' }
  }

  const combined = packs
    .map(
      (p) =>
        `${p.markdown}\n\n<!-- ==== END PACK ${p.packIndex}/${p.packCount} ==== -->\n`,
    )
    .join('\n')

  if (combined.length <= COMBINED_SOFT_CAP) {
    downloadTextFile(
      `a1-ds_${slug}_ALL.md`,
      combined,
      'text/markdown;charset=utf-8',
    )
    return { packCount: packs.length, rowCount, mode: 'single' }
  }

  downloadPacksStaggered(
    packs.map((p) => ({
      name: `${p.filenameBase}.md`,
      body: p.markdown,
      mime: 'text/markdown;charset=utf-8',
    })),
  )
  return { packCount: packs.length, rowCount, mode: 'packs' }
}

export function exportA1ForDeepSeekJsonl(
  bookIndex: BookIndex,
  options: A1DsExportOptions = {},
): { packCount: number; rowCount: number; mode: 'single' | 'packs' } {
  const packs = buildA1DsPacks(bookIndex, options)
  const rowCount = packs.reduce((n, p) => n + p.rows.length, 0)
  if (packs.length === 0) {
    return { packCount: 0, rowCount: 0, mode: 'single' }
  }

  const slug = safeDocSlug(bookIndex.docId)
  if (packs.length === 1) {
    downloadTextFile(
      `${packs[0].filenameBase}.jsonl`,
      packs[0].jsonl,
      'application/x-ndjson',
    )
    return { packCount: 1, rowCount, mode: 'single' }
  }

  const combined = packs.map((p) => p.jsonl).filter(Boolean).join('\n')
  if (combined.length <= COMBINED_SOFT_CAP) {
    downloadTextFile(`a1-ds_${slug}_ALL.jsonl`, combined, 'application/x-ndjson')
    return { packCount: packs.length, rowCount, mode: 'single' }
  }

  downloadPacksStaggered(
    packs.map((p) => ({
      name: `${p.filenameBase}.jsonl`,
      body: p.jsonl,
      mime: 'application/x-ndjson',
    })),
  )
  return { packCount: packs.length, rowCount, mode: 'packs' }
}

