/**
 * 书内名词表 · 材料面与 S₀ / S（无 LLM）。
 * 协议：docs/book-noun-pipeline-protocol-2026-09-14.md
 *
 * 抽词只读 atomSearchText（纯原文 T）；禁止 key/bbox/坐标进池。
 */

import type { BookIndex, AChunk } from '../reasoning/pipelineA'
import {
  atomSearchText,
  isRetrievableAtom,
} from '../reasoning/hybridRetrieve'

export type BookNounEntry = {
  /** ignore-case canonical */
  surface: string
  /** 首见展示形 */
  display: string
  df: number
  bookKeys: string[]
}

export type BookNounIndex = {
  docId: string
  builtAt: number
  /** 规则粗表 */
  s0: BookNounEntry[]
  /** 默写补缺（可空） */
  s1: BookNounEntry[]
  /** dedupe(S₀ ∪ S₁) */
  S: BookNounEntry[]
}

/** 单段可抽词正文（台侧地址与 T 分离） */
export type NounTextUnit = {
  bookKey: string
  page: number
  /** 纯原文 */
  T: string
}

const MASK_CHAR = '█'

/** 最小停用（可扩）；不含专名 */
const STOP_SURFACES = new Set(
  [
    'the',
    'and',
    'for',
    'with',
    'from',
    'that',
    'this',
    'these',
    'those',
    'dans',
    'les',
    'des',
    'une',
    'pour',
    'avec',
    'sur',
    'par',
    'est',
    'sont',
    '如何',
    '什么',
    '怎么',
    '怎样',
    '是否',
    '提到',
    '一个',
    '我们',
    '他们',
    '它们',
    '因为',
    '所以',
    '但是',
    '如果',
    '可以',
    '没有',
    '已经',
    '自己',
  ].map((s) => s.toLowerCase()),
)

export function nounCanonical(surface: string): string {
  return surface.replace(/\s+/g, ' ').trim().toLowerCase()
}

export function collectNounTextUnits(bookIndex: BookIndex): NounTextUnit[] {
  const out: NounTextUnit[] = []
  for (const c of bookIndex.chunks) {
    if (!isRetrievableAtom(c)) continue
    const T = stripMarkupNoise(atomSearchText(c))
    if (T.trim().length < 4) continue
    out.push({ bookKey: c.key, page: c.page, T })
  }
  return out
}

/** 抽词前轻洗净：去 HTML/常见 MD 壳，不删正文专名 */
export function stripMarkupNoise(text: string): string {
  return text
    .replace(/<[^>]+>/g, ' ')
    .replace(/^#{1,6}\s+/gm, '')
    .replace(/\r\n/g, '\n')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim()
}

/**
 * 规则抽 S₀：拉丁专名形态 + 汉字 2–8；停用+过短过滤。
 * 禁用 tokenizeQuery。
 */
export function extractS0FromUnits(units: NounTextUnit[]): BookNounEntry[] {
  const map = new Map<
    string,
    { display: string; df: number; keys: Set<string> }
  >()

  const bump = (raw: string, bookKey: string) => {
    const display = raw.replace(/\s+/g, ' ').trim()
    if (!display || display.length < 2) return
    const canon = nounCanonical(display)
    if (STOP_SURFACES.has(canon)) return
    if (/^[\d\W_]+$/.test(display)) return
    const cur = map.get(canon)
    if (cur) {
      cur.df += 1
      cur.keys.add(bookKey)
    } else {
      map.set(canon, { display, df: 1, keys: new Set([bookKey]) })
    }
  }

  for (const u of units) {
    const t = u.T
    const latin =
      t.match(
        /\b[A-ZÁÉÍÓÚÄÖÜÂÊÎÔÛÀÈÌÒÙÇ][A-Za-zÁÉÍÓÚÄÖÜÂÊÎÔÛÀÈÌÒÙÄÖÜäöüâêîôûàèìòùç\-']{1,40}\b/g,
      ) ?? []
    for (const w of latin) bump(w, u.bookKey)

    const cjk = t.match(/[\u4e00-\u9fff]{2,8}/g) ?? []
    for (const w of cjk) bump(w, u.bookKey)
  }

  const entries: BookNounEntry[] = []
  for (const [surface, v] of map) {
    // 全书仅 1 次且极短的拉丁小写碎片已在形态上排除；汉字单次保留（专名常稀）
    if (v.df >= 80 && surface.length <= 2) continue
    entries.push({
      surface,
      display: v.display,
      df: v.df,
      bookKeys: [...v.keys],
    })
  }
  entries.sort((a, b) => b.df - a.df || a.surface.localeCompare(b.surface))
  return entries
}

export function extractS0FromBookIndex(bookIndex: BookIndex): BookNounEntry[] {
  return extractS0FromUnits(collectNounTextUnits(bookIndex))
}

/**
 * 在 T 上 mask 已入 S₀ 的表面形 → 同长占位残文（大小写不敏感）。
 * 不硬删，避免偏移错乱。
 */
export function maskSurfacesInText(
  text: string,
  surfaces: Iterable<string>,
): string {
  const list = [...surfaces]
    .map((s) => s.trim())
    .filter((s) => s.length >= 2)
    .sort((a, b) => b.length - a.length)
  if (list.length === 0) return text

  let out = text
  for (const s of list) {
    const escaped = s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    const re = new RegExp(escaped, 'gi')
    out = out.replace(re, (m) => MASK_CHAR.repeat(Math.max(1, m.length)))
  }
  return out
}

export function buildResidualUnits(
  units: NounTextUnit[],
  s0: BookNounEntry[],
): NounTextUnit[] {
  const surfaces = s0.map((e) => e.display)
  return units.map((u) => ({
    ...u,
    T: maskSurfacesInText(u.T, surfaces),
  }))
}

export function dedupeNounEntries(
  entries: BookNounEntry[],
): BookNounEntry[] {
  const map = new Map<string, BookNounEntry>()
  for (const e of entries) {
    const canon = nounCanonical(e.surface || e.display)
    if (!canon) continue
    const prev = map.get(canon)
    if (!prev) {
      map.set(canon, {
        surface: canon,
        display: e.display || e.surface,
        df: e.df,
        bookKeys: [...new Set(e.bookKeys)],
      })
      continue
    }
    prev.df += e.df
    const keys = new Set([...prev.bookKeys, ...e.bookKeys])
    prev.bookKeys = [...keys]
  }
  return [...map.values()].sort(
    (a, b) => b.df - a.df || a.surface.localeCompare(b.surface),
  )
}

export function mergeS0S1(
  s0: BookNounEntry[],
  s1: BookNounEntry[],
): BookNounEntry[] {
  return dedupeNounEntries([...s0, ...s1])
}

export function emptyBookNounIndex(docId: string): BookNounIndex {
  return { docId, builtAt: Date.now(), s0: [], s1: [], S: [] }
}

/** 仅规则建表（不开 S₁ LLM） */
export function buildBookNounIndexRulesOnly(
  bookIndex: BookIndex,
): BookNounIndex {
  const s0 = extractS0FromBookIndex(bookIndex)
  return {
    docId: bookIndex.docId,
    builtAt: Date.now(),
    s0,
    s1: [],
    S: dedupeNounEntries(s0),
  }
}

/** 供分批：把残文单位拼成带分隔的批文本（仍无门牌） */
export function joinResidualBatchText(
  units: NounTextUnit[],
  sep = '\n\n',
): string {
  return units
    .map((u) => u.T.trim())
    .filter(Boolean)
    .join(sep)
}

export type ResidualBatch = {
  batchId: string
  /** 本批送 LLM 的纯残文（无 bookKey） */
  text: string
  /** 台侧追溯用，不进 prompt */
  unitBookKeys: string[]
}

/**
 * 按字符预算切残文批；边界重叠 overlapChars，减轻跨批切断短语。
 */
export function chunkResidualUnits(
  units: NounTextUnit[],
  opts?: { maxChars?: number; overlapChars?: number },
): ResidualBatch[] {
  const maxChars = opts?.maxChars ?? 12_000
  const overlapChars = opts?.overlapChars ?? 80
  const batches: ResidualBatch[] = []
  let buf: NounTextUnit[] = []
  let bufLen = 0
  let idx = 0

  const flush = () => {
    if (!buf.length) return
    const text = joinResidualBatchText(buf)
    if (!text.trim()) {
      buf = []
      bufLen = 0
      return
    }
    batches.push({
      batchId: `s1b_${String(++idx).padStart(3, '0')}`,
      text,
      unitBookKeys: buf.map((u) => u.bookKey),
    })
    if (overlapChars > 0 && buf.length > 0) {
      // 简单重叠：保留尾部单位直到长度≈overlap
      const keep: NounTextUnit[] = []
      let keepLen = 0
      for (let i = buf.length - 1; i >= 0; i--) {
        keep.unshift(buf[i]!)
        keepLen += buf[i]!.T.length
        if (keepLen >= overlapChars) break
      }
      buf = keep
      bufLen = keepLen
    } else {
      buf = []
      bufLen = 0
    }
  }

  for (const u of units) {
    const add = u.T.length + 2
    if (buf.length > 0 && bufLen + add > maxChars) flush()
    buf.push(u)
    bufLen += add
  }
  flush()
  // 末次 flush 后若 overlap 残留且已入上一批，避免空尾批
  if (buf.length && batches.length === 0) {
    batches.push({
      batchId: `s1b_${String(++idx).padStart(3, '0')}`,
      text: joinResidualBatchText(buf),
      unitBookKeys: buf.map((u) => u.bookKey),
    })
  }
  return batches.filter((b) => b.text.trim().length > 0)
}

/** 测试/审计辅助：从 chunk 读 T */
export function chunkPlainT(c: AChunk): string {
  return stripMarkupNoise(atomSearchText(c))
}

/**
 * 残文补缺 S₁ · 默写 LLM（协议锁定）
 * docs/book-noun-pipeline-protocol-2026-09-14.md §3
 *
 * 流水线：
 *   BEFORE  制 R → 分批 R_batch（无门牌/坐标）
 *   PROMPT  system + user（见下方常量）
 *   LLM     /api/llm chat/completions
 *   AFTER   本批子串硬闸 → 剔噪 → 最长合并 → 掩串二轮 → 并入 S₁
 */

import { demoAuthHeaders } from '../reasoning/demoAuth'
import { extractJsonObject } from '../reasoning/inferPath'
import { llmThinkingField } from '../reasoning/llmThinking'
import {
  loadDualModelConfig,
  reasonEndpointReady,
  LOCKED_LLM,
} from '../reasoning/modelRuntimeConfig'
import type { BookIndex } from '../reasoning/pipelineA'
import {
  type BookNounEntry,
  type BookNounIndex,
  type ResidualBatch,
  buildResidualUnits,
  chunkResidualUnits,
  collectNounTextUnits,
  dedupeNounEntries,
  extractS0FromBookIndex,
  maskSurfacesInText,
  mergeS0S1,
  nounCanonical,
} from './bookNounIndex'

// ─────────────────────────────────────────────
// PROMPT（补缺默写 · 完整提示词）
// ─────────────────────────────────────────────

export const S1_DICTATION_SYSTEM = [
  '【工种】书内名词表 · 残文补缺 S₁（默写）',
  '【发明权】你只能从用户给出的【本批残文】中抄写连续原文片段；禁止造词、禁止翻译、禁止近义改写、禁止补全残缺词。',
  '【任务】残文中已用实心块「█」盖住规则表 S₀ 已收录的词。请找出仍可能漏网的专名 / 名词 / 名词短语，原样抄出。',
  '【禁止】输出 bookKey、坐标、页码、HTML、解释性句子；不要要求「请分批」；不要发明残文中未出现的拼写。',
  '【输出】仅 JSON（可包在 ```json 中）：{"nouns":["原文片段", "..."]}',
  '【空结果】若无明显漏网专名，返回 {"nouns":[]}',
].join('\n')

export function buildS1DictationUserPrompt(input: {
  batchId: string
  residualText: string
  round: number
}): string {
  const roundNote =
    input.round <= 1
      ? '本轮：首轮默写补缺。'
      : `本轮：第 ${input.round} 轮（已掩去上轮收卷串后的剩余残文）。`
  return [
    `batchId: ${input.batchId}`,
    roundNote,
    '',
    '【本批残文 · 开始】',
    input.residualText,
    '【本批残文 · 结束】',
    '',
    '请只输出 JSON：{"nouns":["..."]}',
  ].join('\n')
}

// ─────────────────────────────────────────────
// LLM 调用
// ─────────────────────────────────────────────

async function flashChat(input: {
  system: string
  user: string
  signal?: AbortSignal
}): Promise<{ ok: true; content: string } | { ok: false; note: string }> {
  const { reason } = loadDualModelConfig()
  if (!reasonEndpointReady(reason)) {
    return { ok: false, note: '推理槽未配置（/api/llm）' }
  }
  const base = (reason.baseUrl.trim() || '/api/llm').replace(/\/$/, '')
  const url = `${base}/chat/completions`
  const headers: Record<string, string> = {
    'Content-Type': 'application/json',
    ...demoAuthHeaders(),
  }
  if (reason.apiKey.trim() && !base.startsWith('/api/')) {
    headers.Authorization = `Bearer ${reason.apiKey.trim()}`
  }
  try {
    if (input.signal?.aborted) {
      return { ok: false, note: 'LLM 已取消' }
    }
    const res = await fetch(url, {
      method: 'POST',
      headers,
      body: JSON.stringify({
        model: reason.model || LOCKED_LLM.chatModel,
        temperature: 0,
        max_tokens: 4096,
        ...llmThinkingField('disabled'),
        messages: [
          { role: 'system', content: input.system },
          { role: 'user', content: input.user },
        ],
      }),
      signal: input.signal,
    })
    if (!res.ok) {
      const errText = await res.text()
      return {
        ok: false,
        note: `LLM HTTP ${res.status}: ${errText.slice(0, 160)}`,
      }
    }
    const data: unknown = await res.json()
    if (
      typeof data !== 'object' ||
      data === null ||
      !('choices' in data) ||
      !Array.isArray((data as { choices: unknown }).choices)
    ) {
      return { ok: false, note: 'LLM 响应无 choices' }
    }
    const content = (
      data as { choices: Array<{ message?: { content?: string } }> }
    ).choices[0]?.message?.content
    if (typeof content !== 'string' || !content.trim()) {
      return { ok: false, note: 'LLM 空内容' }
    }
    return { ok: true, content }
  } catch (e) {
    const aborted =
      input.signal?.aborted ||
      (e instanceof Error &&
        (e.name === 'AbortError' || /abort/i.test(e.message)))
    return {
      ok: false,
      note: aborted
        ? 'LLM 已取消'
        : e instanceof Error
          ? e.message
          : 'LLM 请求失败',
    }
  }
}

// ─────────────────────────────────────────────
// AFTER：解析 → 本批子串硬闸 → 剔噪 → 最长合并
// ─────────────────────────────────────────────

export type S1Reject = {
  raw: string
  reason:
    | 'empty'
    | 'not_substring'
    | 'noise'
    | 'covered_by_longer'
}

const NOISE_EXACT = new Set(
  ['the', 'and', 'dans', 'les', 'des', '如何', '什么', '是否', '提到'].map((s) =>
    s.toLowerCase(),
  ),
)

export function parseS1NounsFromLlm(raw: string): string[] {
  const obj = extractJsonObject(raw)
  if (!obj) return []
  const arr = Array.isArray(obj.nouns) ? obj.nouns : []
  const out: string[] = []
  for (const x of arr) {
    if (typeof x === 'string' && x.trim()) out.push(x.trim())
  }
  return out
}

/**
 * 硬闸：必须是本批 residualText 的连续子串（先敏感匹配；失败再 ignore-case 找回原文切片）。
 * 回配作用域 = 本召输入，禁止调用方传入全书其它批文本。
 */
export function gateNounsAgainstBatchText(
  candidates: string[],
  batchText: string,
): { accepted: string[]; rejected: S1Reject[] } {
  const accepted: string[] = []
  const rejected: S1Reject[] = []

  for (const raw of candidates) {
    const w = raw.replace(/\s+/g, ' ').trim()
    if (!w) {
      rejected.push({ raw, reason: 'empty' })
      continue
    }
    if (NOISE_EXACT.has(w.toLowerCase()) || w.length < 2) {
      rejected.push({ raw: w, reason: 'noise' })
      continue
    }
    if (/^[\d\W_█]+$/.test(w) || /^█+$/.test(w)) {
      rejected.push({ raw: w, reason: 'noise' })
      continue
    }

    let grounded: string | null = null
    const exactAt = batchText.indexOf(w)
    if (exactAt >= 0) {
      grounded = batchText.slice(exactAt, exactAt + w.length)
    } else {
      const lowerHay = batchText.toLowerCase()
      const lowerNeedle = w.toLowerCase()
      const at = lowerHay.indexOf(lowerNeedle)
      if (at >= 0) {
        grounded = batchText.slice(at, at + w.length)
      }
    }
    if (!grounded) {
      rejected.push({ raw: w, reason: 'not_substring' })
      continue
    }
    // 拒绝整段都是 mask 的「命中」
    if (/^█+$/.test(grounded) || !grounded.replace(/█/g, '').trim()) {
      rejected.push({ raw: w, reason: 'noise' })
      continue
    }
    accepted.push(grounded)
  }

  return {
    accepted: mergeLongestSurfaces(accepted),
    rejected,
  }
}

/** 短串被长串覆盖则丢短串 */
export function mergeLongestSurfaces(surfaces: string[]): string[] {
  const uniq: string[] = []
  const seen = new Set<string>()
  for (const s of surfaces) {
    const c = nounCanonical(s)
    if (!c || seen.has(c)) continue
    seen.add(c)
    uniq.push(s)
  }
  uniq.sort((a, b) => b.length - a.length)
  const kept: string[] = []
  for (const s of uniq) {
    const cl = s.toLowerCase()
    if (kept.some((k) => k.toLowerCase().includes(cl) && k.length > s.length)) {
      continue
    }
    kept.push(s)
  }
  return kept
}

function surfacesToS1Entries(
  surfaces: string[],
  unitBookKeys: string[],
): BookNounEntry[] {
  const keys = [...new Set(unitBookKeys.filter(Boolean))]
  return surfaces.map((display) => ({
    surface: nounCanonical(display),
    display,
    df: 1,
    bookKeys: keys,
  }))
}

// ─────────────────────────────────────────────
// 单批：BEFORE 已备好 batch → LLM → AFTER（含掩串二轮）
// ─────────────────────────────────────────────

export type S1BatchRoundAudit = {
  round: number
  residualChars: number
  rawLlm: string
  parsed: string[]
  accepted: string[]
  rejected: S1Reject[]
  note: string
}

export type S1BatchResult = {
  batchId: string
  surfaces: string[]
  rounds: S1BatchRoundAudit[]
  note: string
}

async function runOneDictationRound(input: {
  batchId: string
  residualText: string
  round: number
  signal?: AbortSignal
}): Promise<{
  raw: string
  parsed: string[]
  note: string
  ok: boolean
}> {
  const user = buildS1DictationUserPrompt({
    batchId: input.batchId,
    residualText: input.residualText,
    round: input.round,
  })
  let chat = await flashChat({
    system: S1_DICTATION_SYSTEM,
    user,
    signal: input.signal,
  })
  // JSON / 空：整批重试一次
  if (!chat.ok) {
    return { raw: '', parsed: [], note: chat.note, ok: false }
  }
  let parsed = parseS1NounsFromLlm(chat.content)
  if (parsed.length === 0 && !/\{\s*"nouns"\s*:\s*\[/.test(chat.content)) {
    const retry = await flashChat({
      system: S1_DICTATION_SYSTEM,
      user:
        user +
        '\n\n【重试】上轮输出无法解析为 {"nouns":[...]}。请只输出该 JSON。',
      signal: input.signal,
    })
    if (retry.ok) {
      chat = retry
      parsed = parseS1NounsFromLlm(retry.content)
    }
  }
  return {
    raw: chat.content,
    parsed,
    note: chat.ok ? 'ok' : 'fail',
    ok: true,
  }
}

/**
 * 单批补缺：默写 → 本批回配 → 掩串 → 至多再一轮。
 */
export async function runS1DictationOnBatch(input: {
  batch: ResidualBatch
  /** 含首轮，默认 2 */
  maxRounds?: number
  signal?: AbortSignal
  onProgress?: (msg: string) => void
}): Promise<S1BatchResult> {
  const maxRounds = Math.max(1, input.maxRounds ?? 2)
  let residual = input.batch.text
  const allAccepted: string[] = []
  const rounds: S1BatchRoundAudit[] = []

  for (let round = 1; round <= maxRounds; round++) {
    if (!residual.replace(/█/g, '').trim()) {
      rounds.push({
        round,
        residualChars: residual.length,
        rawLlm: '',
        parsed: [],
        accepted: [],
        rejected: [],
        note: '残文已空，停止',
      })
      break
    }
    input.onProgress?.(
      `S₁ 默写 · ${input.batch.batchId} · 轮${round}/${maxRounds} · ${residual.length} 字…`,
    )
    const llm = await runOneDictationRound({
      batchId: input.batch.batchId,
      residualText: residual,
      round,
      signal: input.signal,
    })
    if (!llm.ok) {
      rounds.push({
        round,
        residualChars: residual.length,
        rawLlm: llm.raw,
        parsed: [],
        accepted: [],
        rejected: [],
        note: llm.note,
      })
      break
    }
    const gated = gateNounsAgainstBatchText(llm.parsed, residual)
    rounds.push({
      round,
      residualChars: residual.length,
      rawLlm: llm.raw,
      parsed: llm.parsed,
      accepted: gated.accepted,
      rejected: gated.rejected,
      note:
        `收×${gated.accepted.length} · 拒×${gated.rejected.length}` +
        (gated.rejected.some((r) => r.reason === 'not_substring')
          ? ' · 含乱编/非本批子串'
          : ''),
    })
    if (gated.accepted.length === 0) break
    for (const s of gated.accepted) allAccepted.push(s)
    // 掩已收串 → 下一轮残文
    residual = maskSurfacesInText(residual, gated.accepted)
  }

  const merged = mergeLongestSurfaces(allAccepted)
  return {
    batchId: input.batch.batchId,
    surfaces: merged,
    rounds,
    note: `批 ${input.batch.batchId} · 收 surface×${merged.length} · 轮次×${rounds.length}`,
  }
}

// ─────────────────────────────────────────────
// 全书入口：BEFORE 全链路 + 各批 LLM + 合成 S
// ─────────────────────────────────────────────

export type RunS1DictationResult = {
  ok: boolean
  index: BookNounIndex
  batchResults: S1BatchResult[]
  note: string
}

/**
 * BEFORE：units → S₀ → mask → 分批
 * LLM+AFTER：每批默写回配
 * 合成：S = dedupe(S₀ ∪ S₁)
 */
export async function runBookNounS1Dictation(input: {
  bookIndex: BookIndex
  /** 已有 S₀ 则复用；否则现场规则抽 */
  s0?: BookNounEntry[]
  maxCharsPerBatch?: number
  maxRoundsPerBatch?: number
  signal?: AbortSignal
  onProgress?: (msg: string) => void
}): Promise<RunS1DictationResult> {
  const units = collectNounTextUnits(input.bookIndex)
  if (units.length === 0) {
    return {
      ok: false,
      index: {
        docId: input.bookIndex.docId,
        builtAt: Date.now(),
        s0: [],
        s1: [],
        S: [],
      },
      batchResults: [],
      note: '无可用原文 T（A1 空或不可检索）',
    }
  }

  const s0 = input.s0?.length
    ? input.s0
    : extractS0FromBookIndex(input.bookIndex)
  input.onProgress?.(`S₀ 规则表 ×${s0.length} · 制残文…`)

  const residualUnits = buildResidualUnits(units, s0)
  const batches = chunkResidualUnits(residualUnits, {
    maxChars: input.maxCharsPerBatch ?? 12_000,
  })
  if (batches.length === 0) {
    return {
      ok: true,
      index: {
        docId: input.bookIndex.docId,
        builtAt: Date.now(),
        s0,
        s1: [],
        S: dedupeNounEntries(s0),
      },
      batchResults: [],
      note: '残文为空（S₀ 可能已盖满）· S=S₀',
    }
  }

  input.onProgress?.(`S₁ 默写 · 共 ${batches.length} 批…`)
  const batchResults: S1BatchResult[] = []
  const s1Acc: BookNounEntry[] = []

  for (const batch of batches) {
    if (input.signal?.aborted) break
    const r = await runS1DictationOnBatch({
      batch,
      maxRounds: input.maxRoundsPerBatch ?? 2,
      signal: input.signal,
      onProgress: input.onProgress,
    })
    batchResults.push(r)
    s1Acc.push(...surfacesToS1Entries(r.surfaces, batch.unitBookKeys))
  }

  const s1 = dedupeNounEntries(s1Acc)
  const S = mergeS0S1(s0, s1)
  const index: BookNounIndex = {
    docId: input.bookIndex.docId,
    builtAt: Date.now(),
    s0,
    s1,
    S,
  }

  return {
    ok: true,
    index,
    batchResults,
    note: `S₀×${s0.length} · S₁×${s1.length} · S×${S.length} · 批×${batchResults.length}`,
  }
}

/** 审计：导出本批将送出的完整 messages（不发网） */
export function previewS1DictationMessages(input: {
  batchId: string
  residualText: string
  round?: number
}): { system: string; user: string } {
  return {
    system: S1_DICTATION_SYSTEM,
    user: buildS1DictationUserPrompt({
