 * LLM+AFTER：每批默写回配
 * 事后 locate 填 bookKeys；S = dedupe(S₀ ∪ S₁)
 */
export async function runBookNounS1Dictation(input: {
  bookIndex: BookIndex
  /** 已有 S₀ 则复用；否则现场规则抽（应尚无 bookKeys 或稍后重 locate） */
  s0?: BookNounEntry[]
  maxCharsPerBatch?: number
  maxRoundsPerBatch?: number
  signal?: AbortSignal
  onProgress?: (msg: string) => void
}): Promise<RunS1DictationResult> {
  const { plains, locs } = collectPlainTextsAndLocs(input.bookIndex)
  if (plains.length === 0) {
    return {
      ok: false,
      index: {
        docId: input.bookIndex.docId,
        builtAt: Date.now(),
        s0: [],
        s1: [],
        S: [],
      },
      batchResults: [],
      note: '无可用原文 T（A1 空或不可检索）',
    }
  }

  const s0raw = input.s0?.length
    ? input.s0
    : extractS0FromPlainTexts(plains)
  input.onProgress?.(`S₀ 规则表 ×${s0raw.length} · 制残文…`)

  const residualPlains = buildResidualPlainTexts(plains, s0raw)
  const batches = chunkResidualPlainTexts(residualPlains, {
    maxChars: input.maxCharsPerBatch ?? 12_000,
  })
  if (batches.length === 0) {
    const s0 = attachBookKeysByLocate(s0raw, plains, locs)
    return {
      ok: true,
      index: {
        docId: input.bookIndex.docId,
        builtAt: Date.now(),
        s0,
        s1: [],
        S: dedupeNounEntries(s0),
      },
      batchResults: [],
      note: '残文为空（S₀ 可能已盖满）· S=S₀',
    }
  }

  input.onProgress?.(`S₁ 默写 · 共 ${batches.length} 批…`)
  const batchResults: S1BatchResult[] = []
  const s1Acc: BookNounEntry[] = []

  for (const batch of batches) {
    if (input.signal?.aborted) break
    const r = await runS1DictationOnBatch({
      batch,
      maxRounds: input.maxRoundsPerBatch ?? 2,
      signal: input.signal,
      onProgress: input.onProgress,
    })
    batchResults.push(r)
    s1Acc.push(...surfacesToS1Entries(r.surfaces))
  }

  const s1located = attachBookKeysByLocate(
    dedupeNounEntries(s1Acc),
    plains,
    locs,
  )
  const s0 = attachBookKeysByLocate(s0raw, plains, locs)
  const S = mergeS0S1(s0, s1located)
  const index: BookNounIndex = {
    docId: input.bookIndex.docId,
    builtAt: Date.now(),
    s0,
    s1: s1located,
    S,
  }

  return {
    ok: true,
    index,
    batchResults,
    note: `S₀×${s0.length} · S₁×${s1located.length} · S×${S.length} · 批×${batchResults.length}`,
