export function attachBookKeysByLocate(
  entries: BookNounEntry[],
  bookIndex: BookIndex,
): BookNounEntry[] {
  const chunks = bookIndex.chunks.filter((c) => isRetrievableAtom(c))
  return entries.map((e) => {
    const needle = (e.display || e.surface).trim()
    if (!needle || needle.length < 2) return { ...e, bookKeys: [] }
