/** 短串被长串覆盖则丢短串 */
export function mergeLongestSurfaces(surfaces: string[]): string[] {
  const uniq: string[] = []
  const seen = new Set<string>()
  for (const s of surfaces) {
    const c = nounCanonical(s)
    if (!c || seen.has(c)) continue
    seen.add(c)
    uniq.push(s)
