  uniq.sort((a, b) => b.length - a.length)
  const kept: string[] = []
  for (const s of uniq) {
    const cl = s.toLowerCase()
    if (kept.some((k) => k.toLowerCase().includes(cl) && k.length > s.length)) {
      continue
    }
    kept.push(s)
  }
  return kept
}

