 * 并集去重后再对 A1 locate → Entry（才带 bookKeys）。
 */

import type { BookIndex, AChunk } from '../reasoning/pipelineA'
import {
  atomSearchText,
  isRetrievableAtom,
} from '../reasoning/hybridRetrieve'

/** 抽词/默写产物：无门牌 */
export type BookNounDraft = {
  surface: string
  display: string
  df: number
}

/** locate 之后：Draft + A1 门牌 */
export type BookNounEntry = BookNounDraft & {
  bookKeys: string[]
}

export type BookNounIndex = {
  docId: string
  builtAt: number
  s0: BookNounEntry[]
  s1: BookNounEntry[]
  S: BookNounEntry[]
}

export type PlainText = {
  T: string
}

export type TextLocation = {
  bookKey: string
  page: number
}

const MASK_CHAR = '█'

const STOP_SURFACES = new Set(
  [
    'the',
    'and',
    'for',
    'with',
    'from',
    'that',
    'this',
    'these',
    'those',
    'dans',
    'les',
    'des',
    'une',
    'pour',
    'avec',
    'sur',
    'par',
    'est',
    'sont',
    '如何',
    '什么',
    '怎么',
    '怎样',
    '是否',
    '提到',
    '一个',
    '我们',
    '他们',
    '它们',
    '因为',
    '所以',
    '但是',
    '如果',
    '可以',
    '没有',
    '已经',
    '自己',
  ].map((s) => s.toLowerCase()),
)

export function nounCanonical(surface: string): string {
  return surface.replace(/\s+/g, ' ').trim().toLowerCase()
}

export function stripMarkupNoise(text: string): string {
  return text
    .replace(/<[^>]+>/g, ' ')
    .replace(/^#{1,6}\s+/gm, '')
    .replace(/\r\n/g, '\n')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim()
}

export function collectPlainTextsAndLocs(bookIndex: BookIndex): {
  plains: PlainText[]
  locs: TextLocation[]
} {
  const plains: PlainText[] = []
  const locs: TextLocation[] = []
  for (const c of bookIndex.chunks) {
    if (!isRetrievableAtom(c)) continue
    const T = stripMarkupNoise(atomSearchText(c))
    if (T.trim().length < 4) continue
    plains.push({ T })
    locs.push({ bookKey: c.key, page: c.page })
  }
  return { plains, locs }
}

export function collectNounTextUnits(bookIndex: BookIndex): PlainText[] {
  return collectPlainTextsAndLocs(bookIndex).plains
}

/** 规则抽 S₀：只出 Draft，不含 bookKeys */
export function extractS0FromPlainTexts(plains: PlainText[]): BookNounDraft[] {
  const map = new Map<string, { display: string; df: number }>()

  const bump = (raw: string) => {
    const display = raw.replace(/\s+/g, ' ').trim()
    if (!display || display.length < 2) return
    const canon = nounCanonical(display)
    if (STOP_SURFACES.has(canon)) return
    if (/^[\d\W_]+$/.test(display)) return
    const cur = map.get(canon)
    if (cur) cur.df += 1
    else map.set(canon, { display, df: 1 })
  }

  for (const { T } of plains) {
    const latin =
      T.match(
        /\b[A-ZÁÉÍÓÚÄÖÜÂÊÎÔÛÀÈÌÒÙÇ][A-Za-zÁÉÍÓÚÄÖÜÂÊÎÔÛÀÈÌÒÙÄÖÜäöüâêîôûàèìòùç\-']{1,40}\b/g,
      ) ?? []
    for (const w of latin) bump(w)

    const cjk = T.match(/[\u4e00-\u9fff]{2,8}/g) ?? []
    for (const w of cjk) bump(w)
  }

  const drafts: BookNounDraft[] = []
  for (const [surface, v] of map) {
    if (v.df >= 80 && surface.length <= 2) continue
    drafts.push({ surface, display: v.display, df: v.df })
  }
  drafts.sort((a, b) => b.df - a.df || a.surface.localeCompare(b.surface))
  return drafts
}

export function extractS0FromBookIndex(bookIndex: BookIndex): BookNounDraft[] {
  return extractS0FromPlainTexts(collectPlainTextsAndLocs(bookIndex).plains)
}

/**
 * 并集去重之后：在 A1 chunks 上定位 → 才产生 bookKeys。
 * 不改 df。同 chunk 可后续取 page/bbox 可视化。
 */
export function attachBookKeysByLocate(
  drafts: BookNounDraft[],
  bookIndex: BookIndex,
): BookNounEntry[] {
  const chunks = bookIndex.chunks.filter((c) => isRetrievableAtom(c))
  return drafts.map((d) => {
    const needle = (d.display || d.surface).trim()
    if (!needle || needle.length < 2) {
      return { ...d, bookKeys: [] }
    }
    const keys = new Set<string>()
    const lowerNeedle = needle.toLowerCase()
    for (const c of chunks) {
      const hay = stripMarkupNoise(atomSearchText(c))
      if (hay.toLowerCase().indexOf(lowerNeedle) < 0) continue
      keys.add(c.key)
    }
    return { ...d, bookKeys: [...keys] }
  })
}

export function maskSurfacesInText(
  text: string,
  surfaces: Iterable<string>,
): string {
  const list = [...surfaces]
    .map((s) => s.trim())
    .filter((s) => s.length >= 2)
    .sort((a, b) => b.length - a.length)
  if (list.length === 0) return text

  let out = text
  for (const s of list) {
    const escaped = s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    const re = new RegExp(escaped, 'gi')
    out = out.replace(re, (m) => MASK_CHAR.repeat(Math.max(1, m.length)))
  }
  return out
}

export function buildResidualPlainTexts(
  plains: PlainText[],
  s0: BookNounDraft[],
): PlainText[] {
  const surfaces = s0.map((e) => e.display)
  return plains.map((p) => ({ T: maskSurfacesInText(p.T, surfaces) }))
}

export function buildResidualUnits(
  plains: PlainText[],
  s0: BookNounDraft[],
): PlainText[] {
  return buildResidualPlainTexts(plains, s0)
}

/**
 * Draft 去重：仅整串 canonical 全等。禁止子串吞并。
 */
export function dedupeNounDrafts(drafts: BookNounDraft[]): BookNounDraft[] {
  const map = new Map<string, BookNounDraft>()
  for (const e of drafts) {
    const canon = nounCanonical(e.surface || e.display)
    if (!canon) continue
    const prev = map.get(canon)
    if (!prev) {
      map.set(canon, {
        surface: canon,
        display: e.display || e.surface,
        df: e.df,
      })
      continue
    }
    prev.df += e.df
  }
  return [...map.values()].sort(
    (a, b) => b.df - a.df || a.surface.localeCompare(b.surface),
  )
}

/** Entry 去重（locate 后）；整串全等才合并 bookKeys */
export function dedupeNounEntries(entries: BookNounEntry[]): BookNounEntry[] {
  const map = new Map<string, BookNounEntry>()
  for (const e of entries) {
    const canon = nounCanonical(e.surface || e.display)
    if (!canon) continue
    const prev = map.get(canon)
    if (!prev) {
      map.set(canon, {
        surface: canon,
        display: e.display || e.surface,
        df: e.df,
        bookKeys: [...new Set(e.bookKeys)],
      })
      continue
    }
    prev.df += e.df
    prev.bookKeys = [...new Set([...prev.bookKeys, ...e.bookKeys])]
  }
  return [...map.values()].sort(
    (a, b) => b.df - a.df || a.surface.localeCompare(b.surface),
  )
}

/** 并集在 Draft 上做；locate 之前调用 */
export function mergeS0S1Drafts(
  s0: BookNounDraft[],
  s1: BookNounDraft[],
): BookNounDraft[] {
  return dedupeNounDrafts([...s0, ...s1])
}

/** locate 后的 Entry 并集 */
export function mergeS0S1(
  s0: BookNounEntry[],
  s1: BookNounEntry[],
): BookNounEntry[] {
  return dedupeNounEntries([...s0, ...s1])
}

export function emptyBookNounIndex(docId: string): BookNounIndex {
  return { docId, builtAt: Date.now(), s0: [], s1: [], S: [] }
}

export function buildBookNounIndexRulesOnly(
  bookIndex: BookIndex,
): BookNounIndex {
  const { plains } = collectPlainTextsAndLocs(bookIndex)
  const s0Draft = extractS0FromPlainTexts(plains)
  const s0 = attachBookKeysByLocate(dedupeNounDrafts(s0Draft), bookIndex)
  return {
    docId: bookIndex.docId,
    builtAt: Date.now(),
    s0,
    s1: [],
    S: dedupeNounEntries(s0),
  }
}

export function joinResidualBatchText(
  plains: PlainText[],
  sep = '\n\n',
): string {
  return plains
    .map((p) => p.T.trim())
    .filter(Boolean)
    .join(sep)
}

export type ResidualBatch = {
  batchId: string
  text: string
  plainIndices: number[]
}

/**
 * 按字符预算切残文批（批间目前不重叠）。
 *
 * ⚠️ 待办提醒（产品已点名）：硬按字数切可能把**同一个名词/短语**劈在批尾与下批批首。
 * 缓解候选：批边界重叠 N 字；按句/词界对齐后再切。
 */
export function chunkResidualPlainTexts(
  plains: PlainText[],
  opts?: { maxChars?: number },
): ResidualBatch[] {
  const maxChars = opts?.maxChars ?? 12_000
  const out: ResidualBatch[] = []
  let curIdx: number[] = []
  let curLen = 0
  let n = 0

  const flush = () => {
    if (!curIdx.length) return
    const slice = curIdx.map((i) => plains[i]!)
    const text = joinResidualBatchText(slice)
    const indices = [...curIdx]
    curIdx = []
    curLen = 0
    if (!text.trim()) return
    out.push({
      batchId: `s1b_${String(++n).padStart(3, '0')}`,
      text,
      plainIndices: indices,
    })
  }

  for (let i = 0; i < plains.length; i++) {
    const add = plains[i]!.T.length + 2
    if (curIdx.length > 0 && curLen + add > maxChars) flush()
    curIdx.push(i)
    curLen += add
  }
  flush()
  return out
}

export function chunkResidualUnits(
  plains: PlainText[],
  opts?: { maxChars?: number },
): ResidualBatch[] {
  return chunkResidualPlainTexts(plains, opts)
}

export function chunkPlainT(c: AChunk): string {
  return stripMarkupNoise(atomSearchText(c))
}

/** 默写收卷表面形 → Draft（无 bookKeys） */
export function surfacesToDrafts(surfaces: string[]): BookNounDraft[] {
  return surfaces.map((display) => ({
    surface: nounCanonical(display),
    display,
    df: 1,
  }))
}

/** @deprecated 用 surfacesToDrafts */
export function surfacesToEntries(surfaces: string[]): BookNounDraft[] {
  return surfacesToDrafts(surfaces)
}

function surfacesToS1Drafts(surfaces: string[]): BookNounDraft[] {
  return surfacesToDrafts(surfaces)
}

