/**
 * BEFORE：纯 T → S₀ Draft → mask → 分批
 * LLM+AFTER：每批默写回配 → S₁ Draft
 * 并集去重（Draft）→ locate(A1) → Entry → S
 */
export async function runBookNounS1Dictation(input: {
  bookIndex: BookIndex
  /** 已有 S₀ Draft；否则现场规则抽 */
  s0?: BookNounDraft[]
  maxCharsPerBatch?: number
  maxRoundsPerBatch?: number
  signal?: AbortSignal
  onProgress?: (msg: string) => void
}): Promise<RunS1DictationResult> {
  const { plains } = collectPlainTextsAndLocs(input.bookIndex)
  if (plains.length === 0) {
    return {
      ok: false,
      index: {
        docId: input.bookIndex.docId,
        builtAt: Date.now(),
        s0: [],
        s1: [],
        S: [],
      },
      batchResults: [],
      note: '无可用原文 T（A1 空或不可检索）',
    }
  }

  const s0Draft = dedupeNounDrafts(
    input.s0?.length ? input.s0 : extractS0FromPlainTexts(plains),
  )
  input.onProgress?.(`S₀ Draft ×${s0Draft.length} · 制残文…`)

  const residualPlains = buildResidualPlainTexts(plains, s0Draft)
  const batches = chunkResidualPlainTexts(residualPlains, {
    maxChars: input.maxCharsPerBatch ?? 12_000,
  })
  if (batches.length === 0) {
    const s0 = attachBookKeysByLocate(s0Draft, input.bookIndex)
    return {
      ok: true,
      index: {
        docId: input.bookIndex.docId,
        builtAt: Date.now(),
        s0,
        s1: [],
        S: s0,
      },
      batchResults: [],
      note: '残文为空（S₀ 可能已盖满）· S=S₀',
    }
  }

  input.onProgress?.(`S₁ 默写 · 共 ${batches.length} 批…`)
  const batchResults: S1BatchResult[] = []
  const s1Acc: BookNounDraft[] = []

  for (const batch of batches) {
    if (input.signal?.aborted) break
    const r = await runS1DictationOnBatch({
      batch,
      maxRounds: input.maxRoundsPerBatch ?? 2,
      signal: input.signal,
      onProgress: input.onProgress,
    })
    batchResults.push(r)
    s1Acc.push(...surfacesToS1Drafts(r.surfaces))
  }

  const s1Draft = dedupeNounDrafts(s1Acc)
  const mergedDraft = dedupeNounDrafts([...s0Draft, ...s1Draft])
  const S = attachBookKeysByLocate(mergedDraft, input.bookIndex)
  const s0 = attachBookKeysByLocate(s0Draft, input.bookIndex)
  const s1 = attachBookKeysByLocate(s1Draft, input.bookIndex)
  // 权威 S 以并集后再 locate 为准；分列 s0/s1 供审计对照
  void mergeS0S1

  const index: BookNounIndex = {
    docId: input.bookIndex.docId,
    builtAt: Date.now(),
    s0,
    s1,
    S,
  }

  return {
    ok: true,
    index,
    batchResults,
    note: `S₀×${s0.length} · S₁×${s1.length} · S×${S.length} · 批×${batchResults.length}`,
  }
}

