/**
 * 书内名词表 · 材料面与 S₀ / S（无 LLM）。
 * 协议：docs/book-noun-pipeline-protocol-2026-09-14.md
 *
 * Draft = surface + display（无 df、无 bookKeys）。
 * 并集去重后再对 A1 locate → Entry（才有 bookKeys）。
 * 出现次数：需要时用 bookKeys.length 或再扫 A1，不在 Draft 预存 df。
 */

import type { BookIndex, AChunk } from '../reasoning/pipelineA'
import {
  atomSearchText,
  isRetrievableAtom,
} from '../reasoning/hybridRetrieve'

/** 抽词/默写产物 */
export type BookNounDraft = {
  surface: string
  display: string
}

/** locate 之后 */
export type BookNounEntry = BookNounDraft & {
  bookKeys: string[]
}

export type BookNounIndex = {
  docId: string
  builtAt: number
  s0: BookNounEntry[]
  s1: BookNounEntry[]
  S: BookNounEntry[]
}

export type PlainText = { T: string }

export type TextLocation = {
  bookKey: string
  page: number
}

const MASK_CHAR = '█'

const STOP_SURFACES = new Set(
  [
    'the',
    'and',
    'for',
    'with',
    'from',
    'that',
    'this',
    'these',
    'those',
    'dans',
    'les',
    'des',
    'une',
    'pour',
    'avec',
    'sur',
    'par',
    'est',
    'sont',
    '如何',
    '什么',
    '怎么',
    '怎样',
    '是否',
    '提到',
    '一个',
    '我们',
    '他们',
    '它们',
    '因为',
    '所以',
    '但是',
    '如果',
    '可以',
    '没有',
    '已经',
    '自己',
  ].map((s) => s.toLowerCase()),
)

export function nounCanonical(surface: string): string {
  return surface.replace(/\s+/g, ' ').trim().toLowerCase()
}

export function stripMarkupNoise(text: string): string {
  return text
    .replace(/<[^>]+>/g, ' ')
    .replace(/^#{1,6}\s+/gm, '')
    .replace(/\r\n/g, '\n')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim()
}

export function collectPlainTextsAndLocs(bookIndex: BookIndex): {
  plains: PlainText[]
  locs: TextLocation[]
} {
  const plains: PlainText[] = []
  const locs: TextLocation[] = []
  for (const c of bookIndex.chunks) {
    if (!isRetrievableAtom(c)) continue
    const T = stripMarkupNoise(atomSearchText(c))
    if (T.trim().length < 4) continue
    plains.push({ T })
    locs.push({ bookKey: c.key, page: c.page })
  }
  return { plains, locs }
}

export function collectNounTextUnits(bookIndex: BookIndex): PlainText[] {
  return collectPlainTextsAndLocs(bookIndex).plains
}

/** 规则抽 S₀：只出 surface/display；内部临时计数仅用于剔超高频短串 */
export function extractS0FromPlainTexts(plains: PlainText[]): BookNounDraft[] {
  const map = new Map<string, { display: string; hit: number }>()

  const bump = (raw: string) => {
    const display = raw.replace(/\s+/g, ' ').trim()
    if (!display || display.length < 2) return
    const canon = nounCanonical(display)
    if (STOP_SURFACES.has(canon)) return
    if (/^[\d\W_]+$/.test(display)) return
    const cur = map.get(canon)
    if (cur) cur.hit += 1
    else map.set(canon, { display, hit: 1 })
  }

  for (const { T } of plains) {
    const latin =
      T.match(
        /\b[A-ZÁÉÍÓÚÄÖÜÂÊÎÔÛÀÈÌÒÙÇ][A-Za-zÁÉÍÓÚÄÖÜÂÊÎÔÛÀÈÌÒÙÄÖÜäöüâêîôûàèìòùç\-']{1,40}\b/g,
      ) ?? []
    for (const w of latin) bump(w)
    const cjk = T.match(/[\u4e00-\u9fff]{2,8}/g) ?? []
    for (const w of cjk) bump(w)
  }

  const drafts: BookNounDraft[] = []
  for (const [surface, v] of map) {
    if (v.hit >= 80 && surface.length <= 2) continue
    drafts.push({ surface, display: v.display })
  }
  drafts.sort((a, b) => a.surface.localeCompare(b.surface))
  return drafts
}

export function extractS0FromBookIndex(bookIndex: BookIndex): BookNounDraft[] {
  return extractS0FromPlainTexts(collectPlainTextsAndLocs(bookIndex).plains)
}

/** 并集去重后：对 A1 定位 → bookKeys。出现次数看 bookKeys.length（或再扫）。 */
export function attachBookKeysByLocate(
  drafts: BookNounDraft[],
  bookIndex: BookIndex,
): BookNounEntry[] {
  const chunks = bookIndex.chunks.filter((c) => isRetrievableAtom(c))
  return drafts.map((d) => {
    const needle = (d.display || d.surface).trim()
    if (!needle || needle.length < 2) return { ...d, bookKeys: [] }
    const keys = new Set<string>()
    const lowerNeedle = needle.toLowerCase()
    for (const c of chunks) {
      const hay = stripMarkupNoise(atomSearchText(c))
      if (hay.toLowerCase().indexOf(lowerNeedle) < 0) continue
      keys.add(c.key)
    }
    return { ...d, bookKeys: [...keys] }
  })
}

export function maskSurfacesInText(
  text: string,
  surfaces: Iterable<string>,
): string {
  const list = [...surfaces]
    .map((s) => s.trim())
    .filter((s) => s.length >= 2)
    .sort((a, b) => b.length - a.length)
  if (list.length === 0) return text
  let out = text
  for (const s of list) {
    const escaped = s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    const re = new RegExp(escaped, 'gi')
    out = out.replace(re, (m) => MASK_CHAR.repeat(Math.max(1, m.length)))
  }
  return out
}

export function buildResidualPlainTexts(
  plains: PlainText[],
  s0: BookNounDraft[],
): PlainText[] {
  const surfaces = s0.map((e) => e.display)
  return plains.map((p) => ({ T: maskSurfacesInText(p.T, surfaces) }))
}

export function buildResidualUnits(
  plains: PlainText[],
  s0: BookNounDraft[],
): PlainText[] {
  return buildResidualPlainTexts(plains, s0)
}

/** 仅整串 canonical 全等；禁止子串吞并 */
export function dedupeNounDrafts(drafts: BookNounDraft[]): BookNounDraft[] {
  const map = new Map<string, BookNounDraft>()
  for (const e of drafts) {
    const canon = nounCanonical(e.surface || e.display)
    if (!canon) continue
    if (map.has(canon)) continue
    map.set(canon, {
      surface: canon,
      display: e.display || e.surface,
    })
  }
  return [...map.values()].sort((a, b) => a.surface.localeCompare(b.surface))
}

export function dedupeNounEntries(entries: BookNounEntry[]): BookNounEntry[] {
  const map = new Map<string, BookNounEntry>()
  for (const e of entries) {
    const canon = nounCanonical(e.surface || e.display)
    if (!canon) continue
    const prev = map.get(canon)
    if (!prev) {
      map.set(canon, {
        surface: canon,
        display: e.display || e.surface,
        bookKeys: [...new Set(e.bookKeys)],
      })
      continue
    }
    prev.bookKeys = [...new Set([...prev.bookKeys, ...e.bookKeys])]
  }
  return [...map.values()].sort((a, b) => a.surface.localeCompare(b.surface))
}

export function mergeS0S1Drafts(
  s0: BookNounDraft[],
  s1: BookNounDraft[],
): BookNounDraft[] {
  return dedupeNounDrafts([...s0, ...s1])
}

export function mergeS0S1(
  s0: BookNounEntry[],
  s1: BookNounEntry[],
): BookNounEntry[] {
  return dedupeNounEntries([...s0, ...s1])
}

export function emptyBookNounIndex(docId: string): BookNounIndex {
  return { docId, builtAt: Date.now(), s0: [], s1: [], S: [] }
}

export function buildBookNounIndexRulesOnly(
  bookIndex: BookIndex,
): BookNounIndex {
  const { plains } = collectPlainTextsAndLocs(bookIndex)
  const s0Draft = dedupeNounDrafts(extractS0FromPlainTexts(plains))
  const s0 = attachBookKeysByLocate(s0Draft, bookIndex)
  return {
    docId: bookIndex.docId,
    builtAt: Date.now(),
    s0,
    s1: [],
    S: s0,
  }
}

export function joinResidualBatchText(
  plains: PlainText[],
  sep = '\n\n',
): string {
  return plains
    .map((p) => p.T.trim())
    .filter(Boolean)
    .join(sep)
}

export type ResidualBatch = {
  batchId: string
  text: string
  plainIndices: number[]
}

/**
 * ⚠️ 批界可能切断同一名词/短语（待缓解：重叠窗 / 按句切）。
 */
export function chunkResidualPlainTexts(
  plains: PlainText[],
  opts?: { maxChars?: number },
): ResidualBatch[] {
  const maxChars = opts?.maxChars ?? 12_000
  const out: ResidualBatch[] = []
  let curIdx: number[] = []
  let curLen = 0
  let n = 0

  const flush = () => {
    if (!curIdx.length) return
    const slice = curIdx.map((i) => plains[i]!)
    const text = joinResidualBatchText(slice)
    const indices = [...curIdx]
    curIdx = []
    curLen = 0
    if (!text.trim()) return
    out.push({
      batchId: `s1b_${String(++n).padStart(3, '0')}`,
      text,
      plainIndices: indices,
    })
  }

  for (let i = 0; i < plains.length; i++) {
    const add = plains[i]!.T.length + 2
    if (curIdx.length > 0 && curLen + add > maxChars) flush()
    curIdx.push(i)
    curLen += add
  }
  flush()
  return out
}

export function chunkResidualUnits(
  plains: PlainText[],
  opts?: { maxChars?: number },
): ResidualBatch[] {
  return chunkResidualPlainTexts(plains, opts)
}

export function chunkPlainT(c: AChunk): string {
  return stripMarkupNoise(atomSearchText(c))
}

export function surfacesToDrafts(surfaces: string[]): BookNounDraft[] {
  return surfaces.map((display) => ({
    surface: nounCanonical(display),
    display,
  }))
}

/** @deprecated */
export function surfacesToEntries(surfaces: string[]): BookNounDraft[] {
  return surfacesToDrafts(surfaces)
}

/**
 * 书内名词表 · 材料面与 S₀ / S（无 LLM）。
 * 协议：docs/book-noun-pipeline-protocol-2026-09-14.md
 *
 * Draft / 定位针 = 同一条「连续原文串」text：
 * - S₀：规则从 T 抠出的串
 * - S₁：LLM 默写 → 本批回配后的原文切片（不是旧 S₀ 的写法）
 * 去重：ignore-case(text) 整串全等；禁止子串吞并。
 * 无 df（频次回 A1）；bookKeys 仅 locate 后写入。
 */

import type { BookIndex, AChunk } from '../reasoning/pipelineA'
import {
  atomSearchText,
  isRetrievableAtom,
} from '../reasoning/hybridRetrieve'

/** 一条名词 = 一条连续原文 */
export type BookNounDraft = {
  /** 书中连续原文（S₁=LLM 回配切片；S₀=规则抠出） */
  text: string
}

export type BookNounEntry = BookNounDraft & {
  bookKeys: string[]
}

export type BookNounIndex = {
  docId: string
  builtAt: number
  s0: BookNounEntry[]
  s1: BookNounEntry[]
  S: BookNounEntry[]
}

export type PlainText = { T: string }

export type TextLocation = {
  bookKey: string
  page: number
}

const MASK_CHAR = '█'

const STOP_SURFACES = new Set(
  [
    'the',
    'and',
    'for',
    'with',
    'from',
    'that',
    'this',
    'these',
    'those',
    'dans',
    'les',
    'des',
    'une',
    'pour',
    'avec',
    'sur',
    'par',
    'est',
    'sont',
    '如何',
    '什么',
    '怎么',
    '怎样',
    '是否',
    '提到',
    '一个',
    '我们',
    '他们',
    '它们',
    '因为',
    '所以',
    '但是',
    '如果',
    '可以',
    '没有',
    '已经',
    '自己',
  ].map((s) => s.toLowerCase()),
)

export function nounCanonical(text: string): string {
  return text.replace(/\s+/g, ' ').trim().toLowerCase()
}

export function stripMarkupNoise(text: string): string {
  return text
    .replace(/<[^>]+>/g, ' ')
    .replace(/^#{1,6}\s+/gm, '')
    .replace(/\r\n/g, '\n')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim()
}

export function collectPlainTextsAndLocs(bookIndex: BookIndex): {
  plains: PlainText[]
  locs: TextLocation[]
} {
  const plains: PlainText[] = []
  const locs: TextLocation[] = []
  for (const c of bookIndex.chunks) {
    if (!isRetrievableAtom(c)) continue
    const T = stripMarkupNoise(atomSearchText(c))
    if (T.trim().length < 4) continue
    plains.push({ T })
    locs.push({ bookKey: c.key, page: c.page })
  }
  return { plains, locs }
}

export function collectNounTextUnits(bookIndex: BookIndex): PlainText[] {
  return collectPlainTextsAndLocs(bookIndex).plains
}

export function extractS0FromPlainTexts(plains: PlainText[]): BookNounDraft[] {
  const map = new Map<string, string>() // canon → first text
  const hit = new Map<string, number>()

  const bump = (raw: string) => {
    const text = raw.replace(/\s+/g, ' ').trim()
    if (!text || text.length < 2) return
    const canon = nounCanonical(text)
    if (STOP_SURFACES.has(canon)) return
    if (/^[\d\W_]+$/.test(text)) return
    if (!map.has(canon)) map.set(canon, text)
    hit.set(canon, (hit.get(canon) ?? 0) + 1)
  }

  for (const { T } of plains) {
    const latin =
      T.match(
        /\b[A-ZÁÉÍÓÚÄÖÜÂÊÎÔÛÀÈÌÒÙÇ][A-Za-zÁÉÍÓÚÄÖÜÂÊÎÔÛÀÈÌÒÙÄÖÜäöüâêîôûàèìòùç\-']{1,40}\b/g,
      ) ?? []
    for (const w of latin) bump(w)
    const cjk = T.match(/[\u4e00-\u9fff]{2,8}/g) ?? []
    for (const w of cjk) bump(w)
  }

  const drafts: BookNounDraft[] = []
  for (const [canon, text] of map) {
    if ((hit.get(canon) ?? 0) >= 80 && canon.length <= 2) continue
    drafts.push({ text })
  }
  drafts.sort((a, b) => nounCanonical(a.text).localeCompare(nounCanonical(b.text)))
  return drafts
}

export function extractS0FromBookIndex(bookIndex: BookIndex): BookNounDraft[] {
  return extractS0FromPlainTexts(collectPlainTextsAndLocs(bookIndex).plains)
}

/**
 * 用 draft.text（S₁=LLM 回配串）在 A1 上定位。
 * 不用任何「旧表里的另一套写法」。
 */
export function attachBookKeysByLocate(
  drafts: BookNounDraft[],
  bookIndex: BookIndex,
): BookNounEntry[] {
  const chunks = bookIndex.chunks.filter((c) => isRetrievableAtom(c))
  return drafts.map((d) => {
    const needle = d.text.trim()
    if (!needle || needle.length < 2) return { text: d.text, bookKeys: [] }
    const keys = new Set<string>()
    const lowerNeedle = needle.toLowerCase()
    for (const c of chunks) {
      const hay = stripMarkupNoise(atomSearchText(c))
      if (hay.toLowerCase().indexOf(lowerNeedle) < 0) continue
      keys.add(c.key)
    }
    return { text: needle, bookKeys: [...keys] }
  })
}

export function maskSurfacesInText(
  text: string,
  surfaces: Iterable<string>,
): string {
  const list = [...surfaces]
    .map((s) => s.trim())
    .filter((s) => s.length >= 2)
    .sort((a, b) => b.length - a.length)
  if (list.length === 0) return text
  let out = text
  for (const s of list) {
    const escaped = s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    const re = new RegExp(escaped, 'gi')
    out = out.replace(re, (m) => MASK_CHAR.repeat(Math.max(1, m.length)))
  }
  return out
}

export function buildResidualPlainTexts(
  plains: PlainText[],
  s0: BookNounDraft[],
): PlainText[] {
  const surfaces = s0.map((e) => e.text)
  return plains.map((p) => ({ T: maskSurfacesInText(p.T, surfaces) }))
}

export function buildResidualUnits(
  plains: PlainText[],
  s0: BookNounDraft[],
): PlainText[] {
  return buildResidualPlainTexts(plains, s0)
}

export function dedupeNounDrafts(drafts: BookNounDraft[]): BookNounDraft[] {
  const map = new Map<string, BookNounDraft>()
  for (const e of drafts) {
    const text = e.text.replace(/\s+/g, ' ').trim()
    const canon = nounCanonical(text)
    if (!canon) continue
    if (map.has(canon)) continue
    map.set(canon, { text })
  }
  return [...map.values()].sort((a, b) =>
    nounCanonical(a.text).localeCompare(nounCanonical(b.text)),
  )
}

export function dedupeNounEntries(entries: BookNounEntry[]): BookNounEntry[] {
  const map = new Map<string, BookNounEntry>()
  for (const e of entries) {
    const text = e.text.replace(/\s+/g, ' ').trim()
    const canon = nounCanonical(text)
    if (!canon) continue
    const prev = map.get(canon)
    if (!prev) {
      map.set(canon, { text, bookKeys: [...new Set(e.bookKeys)] })
      continue
    }
    prev.bookKeys = [...new Set([...prev.bookKeys, ...e.bookKeys])]
  }
  return [...map.values()].sort((a, b) =>
    nounCanonical(a.text).localeCompare(nounCanonical(b.text)),
  )
}

export function mergeS0S1Drafts(
  s0: BookNounDraft[],
  s1: BookNounDraft[],
): BookNounDraft[] {
  return dedupeNounDrafts([...s0, ...s1])
}

export function mergeS0S1(
  s0: BookNounEntry[],
  s1: BookNounEntry[],
): BookNounEntry[] {
  return dedupeNounEntries([...s0, ...s1])
}

export function emptyBookNounIndex(docId: string): BookNounIndex {
  return { docId, builtAt: Date.now(), s0: [], s1: [], S: [] }
}

export function buildBookNounIndexRulesOnly(
  bookIndex: BookIndex,
): BookNounIndex {
  const { plains } = collectPlainTextsAndLocs(bookIndex)
  const s0Draft = dedupeNounDrafts(extractS0FromPlainTexts(plains))
  const s0 = attachBookKeysByLocate(s0Draft, bookIndex)
  return {
    docId: bookIndex.docId,
    builtAt: Date.now(),
    s0,
    s1: [],
    S: s0,
  }
}

export function joinResidualBatchText(
  plains: PlainText[],
  sep = '\n\n',
): string {
  return plains
    .map((p) => p.T.trim())
    .filter(Boolean)
    .join(sep)
}

export type ResidualBatch = {
  batchId: string
  text: string
  plainIndices: number[]
}

/** ⚠️ 批界可能切断名词（待缓解）。 */
export function chunkResidualPlainTexts(
  plains: PlainText[],
  opts?: { maxChars?: number },
): ResidualBatch[] {
  const maxChars = opts?.maxChars ?? 12_000
  const out: ResidualBatch[] = []
  let curIdx: number[] = []
  let curLen = 0
  let n = 0

  const flush = () => {
    if (!curIdx.length) return
    const slice = curIdx.map((i) => plains[i]!)
    const text = joinResidualBatchText(slice)
    const indices = [...curIdx]
    curIdx = []
    curLen = 0
    if (!text.trim()) return
    out.push({
      batchId: `s1b_${String(++n).padStart(3, '0')}`,
      text,
      plainIndices: indices,
    })
  }

  for (let i = 0; i < plains.length; i++) {
    const add = plains[i]!.T.length + 2
    if (curIdx.length > 0 && curLen + add > maxChars) flush()
    curIdx.push(i)
    curLen += add
  }
  flush()
  return out
}

export function chunkResidualUnits(
  plains: PlainText[],
  opts?: { maxChars?: number },
): ResidualBatch[] {
  return chunkResidualPlainTexts(plains, opts)
}

export function chunkPlainT(c: AChunk): string {
  return stripMarkupNoise(atomSearchText(c))
}

/** LLM/规则收下的连续串 → Draft */
export function surfacesToDrafts(surfaces: string[]): BookNounDraft[] {
  return surfaces.map((text) => ({ text: text.replace(/\s+/g, ' ').trim() }))
}

export function surfacesToEntries(surfaces: string[]): BookNounDraft[] {
  return surfacesToDrafts(surfaces)
}

