/**
 * 按字符预算切残文批。
 *
 * **批界切断缓解（共识）**：flush 时把尾部约 `overlapChars` 字所覆盖的
 * plain units **重叠带进下一批**，使跨 unit 的短语至少在一批内完整出现。
 * 重复默写由后续整串 dedupe 消化。默认 overlap=400。
 * 仍按整 unit 切，从不在单段 T 中间切开。
 */
export function chunkResidualPlainTexts(
  plains: PlainText[],
  opts?: { maxChars?: number; overlapChars?: number },
): ResidualBatch[] {
  const maxChars = opts?.maxChars ?? 12_000
  const overlapChars = Math.max(0, opts?.overlapChars ?? 400)
  const out: ResidualBatch[] = []
  let curIdx: number[] = []
  let curLen = 0
  let n = 0

  const flush = (carryOverlap: boolean) => {
    if (!curIdx.length) return
    const indices = [...curIdx]
    const text = joinResidualBatchText(indices.map((i) => plains[i]!))
    if (!text.trim()) {
      curIdx = []
      curLen = 0
      return
    }
    out.push({
      batchId: `s1b_${String(++n).padStart(3, '0')}`,
      text,
      plainIndices: indices,
    })

    if (!carryOverlap || overlapChars <= 0 || indices.length === 0) {
      curIdx = []
      curLen = 0
      return
    }
    // 尾部重叠：从批末往前攒够 overlapChars 的 units，作为下一批开头
    const keep: number[] = []
    let keepLen = 0
    for (let j = indices.length - 1; j >= 0; j--) {
      const i = indices[j]!
      keep.unshift(i)
      keepLen += plains[i]!.T.length + 2
      if (keepLen >= overlapChars) break
    }
    // 整批都叠进去就失去前进 → 至少丢掉最前一个 unit
    if (keep.length >= indices.length && indices.length > 1) {
      keep.shift()
      keepLen = keep.reduce((n, i) => n + plains[i]!.T.length + 2, 0)
    }
    curIdx = keep
    curLen = keepLen
  }

  for (let i = 0; i < plains.length; i++) {
    const add = plains[i]!.T.length + 2
    if (curIdx.length > 0 && curLen + add > maxChars) {
      flush(true)
      // 重叠带入后仍塞不下超长单 unit：强制独批，避免死循环
      if (curIdx.length > 0 && curLen + add > maxChars) {
        flush(false)
      }
    }
    curIdx.push(i)
    curLen += add
  }
  flush(false)
  return out
}

