export type ResidualBatch = {
  batchId: string
  text: string
  plainIndices: number[]
}

type NounSpan = { start: number; end: number; text: string }

/**
 * 在一段正文里按与 S₀ 相同形态扫「名词样」连续串（含位置）。
 * 跳过纯掩码 █。
 */
export function listNounSpansInText(text: string): NounSpan[] {
  const spans: NounSpan[] = []
  const push = (m: RegExpExecArray) => {
    const t = m[0] ?? ''
    if (!t || /^█+$/.test(t)) return
    if (STOP_SURFACES.has(nounCanonical(t))) return
    spans.push({ start: m.index, end: m.index + t.length, text: t })
  }
  const latin =
    /\b[A-ZÁÉÍÓÚÄÖÜÂÊÎÔÛÀÈÌÒÙÇ][A-Za-zÁÉÍÓÚÄÖÜÂÊÎÔÛÀÈÌÒÙÄÖÜäöüâêîôûàèìòùç\-']{1,40}\b/g
  const cjk = /[\u4e00-\u9fff]{2,8}/g
  let m: RegExpExecArray | null
  while ((m = latin.exec(text))) push(m)
  while ((m = cjk.exec(text))) push(m)
  spans.sort((a, b) => a.start - b.start || b.end - a.end)
  // 同起点留更长；简单去重重叠短串
  const out: NounSpan[] = []
  for (const s of spans) {
    const prev = out[out.length - 1]
    if (prev && s.start < prev.end) continue
    out.push(s)
  }
  return out
}

/**
 * 批界重叠后缀：从「截断处最近一个名词」再往前 `priorNouns` 个名词起，
 * 一直截到本批末尾。
 *
 * 例：… N1 N2 拉康 | 成员…
 * 截在拉康后 → 从 N1（拉康前 2 个名词）起到批末（含拉康）带进下一批，
 * 与「成员」同窗，避免短语被拆开。
 */
export function overlapSuffixByPriorNouns(
  batchText: string,
  priorNouns = 2,
): string {
  const spans = listNounSpansInText(batchText)
  if (spans.length === 0) {
    // 无名词样串：退回批末一小截（≤64 字），避免空重叠
    return batchText.slice(Math.max(0, batchText.length - 64))
  }
  const lastIdx = spans.length - 1
  const fromIdx = Math.max(0, lastIdx - Math.max(0, priorNouns))
  const start = spans[fromIdx]!.start
  return batchText.slice(start).trim()
}

/**
 * 按字符预算切残文批；整 unit 加减，从不在单段 T 中间砍。
 *
 * **批界缓解（产品口径）**：不是按 N 字叠 unit，而是——
 * 在本批末尾找到最靠近截断的名词（如「拉康」），再往前数 `priorNouns`（默认 2）
 * 个名词，从那里截到批末，作为后缀贴进下一批开头（与「成员」同窗）。
 */
export function chunkResidualPlainTexts(
  plains: PlainText[],
  opts?: { maxChars?: number; priorNouns?: number },
): ResidualBatch[] {
  const maxChars = opts?.maxChars ?? 12_000
  const priorNouns = opts?.priorNouns ?? 2
  const out: ResidualBatch[] = []
  let curIdx: number[] = []
  let curLen = 0
  let n = 0
  let pendingOverlap = ''

  const flush = (carryOverlap: boolean) => {
    if (!curIdx.length && !pendingOverlap) return
    const indices = [...curIdx]
    const body = joinResidualBatchText(indices.map((i) => plains[i]!))
    const text = pendingOverlap
      ? `${pendingOverlap}\n\n${body}`.trim()
      : body
    pendingOverlap = ''
    curIdx = []
    curLen = 0
    if (!text.trim()) return
    out.push({
      batchId: `s1b_${String(++n).padStart(3, '0')}`,
      text,
      plainIndices: indices,
    })
    if (carryOverlap && body.trim()) {
      pendingOverlap = overlapSuffixByPriorNouns(body, priorNouns)
    }
  }

  for (let i = 0; i < plains.length; i++) {
    const add = plains[i]!.T.length + 2
    if (curIdx.length > 0 && curLen + add > maxChars) {
      flush(true)
    }
    curIdx.push(i)
    curLen += plains[i]!.T.length + 2
    // 单 unit 超大：独自成批（不 overlap 进死循环）
    if (curIdx.length === 1 && curLen > maxChars) {
      flush(false)
    }
  }
  flush(false)
  // 若最后一次 flush(false) 前仍挂着上一批 overlap 且 cur 已空——已在 flush 开头处理
  if (pendingOverlap && out.length > 0) {
    // 不应残留；保险清空
    pendingOverlap = ''
  }
  return out
}

