function findAllS0Offsets(
  haystack: string,
  s0: BookNounDraft[],
): Array<{ start: number; end: number }> {
  const hits: Array<{ start: number; end: number }> = []
  const lowerHay = haystack.toLowerCase()
  for (const d of s0) {
    const needle = d.text.trim()
    if (needle.length < 2) continue
    const lower = needle.toLowerCase()
    let from = 0
    while (from < lowerHay.length) {
      const at = lowerHay.indexOf(lower, from)
      if (at < 0) break
      hits.push({ start: at, end: at + needle.length })
      from = at + Math.max(1, needle.length)
    }
  }
  hits.sort((a, b) => a.start - b.start || a.end - b.end)
  // 合并重叠命中
  const merged: Array<{ start: number; end: number }> = []
  for (const h of hits) {
    const prev = merged[merged.length - 1]
    if (prev && h.start <= prev.end) {
      prev.end = Math.max(prev.end, h.end)
    } else {
      merged.push({ ...h })
    }
  }
  return merged
}

/**
 * 主分批：规则 S₀ 落点之间的残文间隙 = 可并行任务；
 * 单间隙过长 → 间隙内串联（priorNouns 重叠）。
 *
 * plains 与 residualPlains 须同序、同长拼接（mask 同长占位），偏移才对齐。
 */
export function buildS1BatchesByS0Gaps(input: {
  plains: PlainText[]
  residualPlains: PlainText[]
  s0: BookNounDraft[]
  maxChars?: number
  priorNouns?: number
}): ResidualBatch[] {
  const maxChars = input.maxChars ?? 12_000
  const priorNouns = input.priorNouns ?? 2
  const sep = '\n\n'
  const original = joinResidualBatchText(input.plains, sep)
  const residual = joinResidualBatchText(input.residualPlains, sep)
  if (!residual.trim()) return []

  const anchors = findAllS0Offsets(original, input.s0)
  const cuts: number[] = [0]
  for (const a of anchors) {
    cuts.push(a.start, a.end)
  }
  cuts.push(Math.max(original.length, residual.length))
  // 间隙：锚点之外的区间 [cuts[i], cuts[i+1]) 中，落在「名词外」的才是残文间隙
  // 更直接：间隙 = 相邻 S₀ 命中之间 (prev.end, next.start)，外加头尾
  const gaps: Array<{ start: number; end: number }> = []
  if (anchors.length === 0) {
    gaps.push({ start: 0, end: residual.length })
  } else {
    if (anchors[0]!.start > 0) {
      gaps.push({ start: 0, end: anchors[0]!.start })
    }
    for (let i = 0; i < anchors.length - 1; i++) {
      const a = anchors[i]!.end
      const b = anchors[i + 1]!.start
      if (b > a) gaps.push({ start: a, end: b })
    }
    const last = anchors[anchors.length - 1]!.end
    if (last < residual.length) {
      gaps.push({ start: last, end: residual.length })
    }
  }

  const batches: ResidualBatch[] = []
  let gi = 0
  for (const g of gaps) {
    const slice = residual.slice(g.start, g.end)
    // 去掉几乎全是掩码/空白的间隙
    const useful = slice.replace(/█/g, '').trim()
    if (useful.length < 4) continue
    gi += 1
    const gapId = `gap${String(gi).padStart(3, '0')}`
    if (slice.length <= maxChars) {
      batches.push({
        batchId: `s1_${gapId}`,
        text: slice.trim(),
        plainIndices: [],
      })
    } else {
      // 段内串联
      const parts = chunkLongTextSerial(slice, {
        maxChars,
        priorNouns,
        batchIdPrefix: `s1_${gapId}`,
      })
      batches.push(...parts)
    }
  }
  return batches
}

